export { AIBuilder } from '@/components/formedible/ai/ai-builder';
export { AiFormRenderer, parseAiToFormedible } from '@/components/formedible/ai/ai-form-renderer';
export { ChatInterface, generateAiFormCode } from '@/components/formedible/ai/chat-interface';
export { createDefaultProviderConfig, providerOptions, ProviderSelection } from '@/components/formedible/ai/provider-selection';
export { extractFormCode } from '@/lib/formedible/ai-parser';
export type {
  AiConversation,
  AiFormParseResult,
  AiGenerationRequest,
  AiGenerationResult,
  AiMessage,
  AIBuilderMode,
  AiParserConfig,
  BackendConfig,
  ProviderConfig,
} from '@/lib/formedible/ai-types';

'use client';

import { useEffect, useRef, useState } from 'react';

import { AiFormRenderer } from '@/components/formedible/ai/ai-form-renderer';
import { ChatInterface } from '@/components/formedible/ai/chat-interface';
import { createDefaultProviderConfig, ProviderSelection, validateProviderConfig } from '@/components/formedible/ai/provider-selection';
import { Button } from '@/components/ui/button';
import type { AiConversation, AiGenerationRequest, AiGenerationResult, AiMessage, AIBuilderMode, BackendConfig, ProviderConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export const STORAGE_KEYS = {
  providerConfig: 'formedible-ai-builder-provider-config',
  conversations: 'formedible-ai-builder-conversations',
  uiState: 'formedible-ai-builder-ui-state',
} as const;

export const AI_BUILDER_DEFAULT_MODE: AIBuilderMode = 'direct';

interface PersistedUiState {
  readonly currentConversationId?: string;
}

export interface PersistedAIBuilderState {
  readonly providerConfig: ProviderConfig;
  readonly conversations: readonly AiConversation[];
  readonly currentConversationId?: string;
}

export interface AIBuilderProps {
  readonly className?: string;
  readonly mode?: AIBuilderMode;
  readonly backendConfig?: BackendConfig;
  readonly providerConfig?: ProviderConfig;
  readonly onProviderConfigChange?: (providerConfig: ProviderConfig) => void;
  readonly onFormGenerated?: (formCode: string) => void;
  readonly onFormSubmit?: (formData: FormedibleFormValues) => void | Promise<void>;
  readonly generateForm?: (request: AiGenerationRequest) => Promise<AiGenerationResult>;
}

export function canUseStorage(): boolean {
  if (typeof window === 'undefined') {
    return false;
  }

  try {
    return typeof window.localStorage !== 'undefined';
  } catch {
    return false;
  }
}

export function readJson<TValue>(key: string, fallback: TValue): TValue {
  if (!canUseStorage()) {
    return fallback;
  }

  try {
    const storedValue = window.localStorage.getItem(key);
    return storedValue ? (JSON.parse(storedValue) as TValue) : fallback;
  } catch {
    return fallback;
  }
}

export function writeJson<TValue>(key: string, value: TValue) {
  if (!canUseStorage()) {
    return;
  }

  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    return;
  }
}

export function readPersistedAIBuilderState(controlledProviderConfig?: ProviderConfig): PersistedAIBuilderState {
  return {
    providerConfig: controlledProviderConfig ?? readJson(STORAGE_KEYS.providerConfig, createDefaultProviderConfig()),
    conversations: readJson(STORAGE_KEYS.conversations, [] as readonly AiConversation[]),
    currentConversationId: readJson<PersistedUiState>(STORAGE_KEYS.uiState, {}).currentConversationId,
  };
}

export interface ConversationUpdateResult {
  readonly conversations: readonly AiConversation[];
  readonly conversationId: string;
}

export function createConversation(messages: readonly AiMessage[], formCode?: string, existingConversation?: AiConversation): AiConversation {
  const firstUserMessage = messages.find((message) => message.role === 'user');
  const now = Date.now();

  return {
    id: existingConversation?.id ?? `conversation_${now}_${Math.random().toString(36).slice(2)}`,
    title: existingConversation?.title || firstUserMessage?.content.slice(0, 48) || 'New AI form',
    messages,
    formCode,
    createdAt: existingConversation?.createdAt ?? now,
    updatedAt: now,
  };
}

export function upsertConversation(
  previousConversations: readonly AiConversation[],
  activeConversationId: string | undefined,
  nextMessages: readonly AiMessage[],
): ConversationUpdateResult {
  const existingConversation = previousConversations.find((conversationEntry) => conversationEntry.id === activeConversationId);
  const nextConversation = createConversation(nextMessages, getLastFormCode(nextMessages) || existingConversation?.formCode, existingConversation);

  if (existingConversation) {
    return {
      conversationId: nextConversation.id,
      conversations: previousConversations.map((conversationEntry) => (conversationEntry.id === nextConversation.id ? nextConversation : conversationEntry)),
    };
  }

  return {
    conversationId: nextConversation.id,
    conversations: [...previousConversations, nextConversation],
  };
}

function getLastFormCode(messages: readonly AiMessage[]): string {
  const messageWithForm = [...messages].reverse().find((message) => message.formCode);
  return messageWithForm?.formCode ?? '';
}

export function AIBuilder({
  className,
  mode = AI_BUILDER_DEFAULT_MODE,
  backendConfig,
  providerConfig: controlledProviderConfig,
  onProviderConfigChange,
  onFormGenerated,
  onFormSubmit,
  generateForm,
}: AIBuilderProps) {
  const [internalProviderConfig, setInternalProviderConfig] = useState<ProviderConfig>(() => readPersistedAIBuilderState(controlledProviderConfig).providerConfig);
  const [conversations, setConversations] = useState<readonly AiConversation[]>(() => readPersistedAIBuilderState().conversations);
  const [currentConversationId, setCurrentConversationId] = useState<string | undefined>(() => readPersistedAIBuilderState().currentConversationId);
  const currentConversationIdRef = useRef<string | undefined>(currentConversationId);
  const providerConfig = controlledProviderConfig ?? internalProviderConfig;
  const currentConversation = conversations.find((conversation) => conversation.id === currentConversationId);
  const messages = currentConversation?.messages ?? [];
  const formCode = currentConversation?.formCode ?? getLastFormCode(messages);
  const providerValidationError = mode === 'direct' ? validateProviderConfig(providerConfig) : undefined;

  useEffect(() => {
    if (!controlledProviderConfig) {
      writeJson(STORAGE_KEYS.providerConfig, internalProviderConfig);
    }
  }, [controlledProviderConfig, internalProviderConfig]);

  useEffect(() => {
    writeJson(STORAGE_KEYS.conversations, conversations);
  }, [conversations]);

  useEffect(() => {
    currentConversationIdRef.current = currentConversationId;
    writeJson(STORAGE_KEYS.uiState, { currentConversationId });
  }, [currentConversationId]);

  function updateProviderConfig(nextConfig: ProviderConfig) {
    setInternalProviderConfig(nextConfig);
    onProviderConfigChange?.(nextConfig);
  }

  function updateMessages(nextMessages: readonly AiMessage[]) {
    setConversations((previousConversations) => {
      const result = upsertConversation(previousConversations, currentConversationIdRef.current, nextMessages);
      currentConversationIdRef.current = result.conversationId;
      setCurrentConversationId(result.conversationId);

      return result.conversations;
    });
  }

  function updateFormCode(nextFormCode: string) {
    const activeConversationId = currentConversationIdRef.current;
    setConversations((previousConversations) => previousConversations.map((conversationEntry) => (conversationEntry.id === activeConversationId ? { ...conversationEntry, formCode: nextFormCode, updatedAt: Date.now() } : conversationEntry)));
    onFormGenerated?.(nextFormCode);
  }

  function startNewConversation() {
    currentConversationIdRef.current = undefined;
    setCurrentConversationId(undefined);
  }

  function selectConversation(conversationId: string) {
    currentConversationIdRef.current = conversationId;
    setCurrentConversationId(conversationId);
  }

  return (
    <section className={cn('grid min-h-[640px] gap-4 lg:grid-cols-[360px_1fr]', className)} data-conversation-id={currentConversationId ?? 'new'}>
      <div className="flex min-h-0 flex-col gap-4">
        <ProviderSelection value={providerConfig} onChange={updateProviderConfig} />
        {providerValidationError ? <p className="rounded-md border border-destructive/40 p-2 text-sm text-destructive">{providerValidationError}</p> : null}
        <div className="grid gap-2 rounded-lg border p-3">
          <Button type="button" variant="outline" onClick={startNewConversation}>New conversation</Button>
          {conversations.length > 0 ? (
            <div className="grid gap-1">
              {conversations.map((conversation) => (
                <Button key={conversation.id} type="button" variant={conversation.id === currentConversationId ? 'default' : 'ghost'} onClick={() => selectConversation(conversation.id)}>
                  {conversation.title}
                </Button>
              ))}
            </div>
          ) : null}
        </div>
        <ChatInterface
          providerConfig={providerConfig}
          mode={mode}
          backendConfig={backendConfig}
          messages={messages}
          onMessagesChange={updateMessages}
          onFormGenerated={updateFormCode}
          generateForm={generateForm}
          conversationId={currentConversationId}
          className="min-h-[420px]"
        />
      </div>
      <div className="min-h-0 rounded-lg border p-4">
        {formCode ? (
          <AiFormRenderer code={formCode} onSubmit={onFormSubmit} className="space-y-4" />
        ) : (
          <div className="flex h-full min-h-[320px] items-center justify-center text-sm text-muted-foreground">Generated forms appear here.</div>
        )}
      </div>
    </section>
  );
}

export type { AiConversation, AIBuilderMode, BackendConfig, ProviderConfig } from '@/lib/formedible/ai-types';

'use client';

import { useEffect, useState } from 'react';

import { useFormedible } from '@/hooks/use-formedible';
import { parseAiToFormedible } from '@/lib/formedible/ai-parser';
import type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';

export interface AiFormRendererProps {
  readonly code: string;
  readonly isStreaming?: boolean;
  readonly onParseComplete?: (result: AiFormParseResult) => void;
  readonly onSubmit?: (formData: FormedibleFormValues) => void | Promise<void>;
  readonly className?: string;
  readonly parserConfig?: AiParserConfig;
}

function EmptyForm({ className, message }: { readonly className?: string; readonly message: string }) {
  return <div className={className}>{message}</div>;
}

function ParsedForm({ className, options }: { readonly className?: string; readonly options: UseFormedibleOptions<FormedibleFormValues> }) {
  const { Form } = useFormedible(options);

  return <Form className={className} />;
}

export function AiFormRenderer({ code, isStreaming, onParseComplete, onSubmit, className, parserConfig }: AiFormRendererProps) {
  const [parseResult, setParseResult] = useState<AiFormParseResult>(() => parseAiToFormedible(code, parserConfig));

  useEffect(() => {
    if (isStreaming) {
      return;
    }

    const nextResult = parseAiToFormedible(code, parserConfig);
    setParseResult(nextResult);
    onParseComplete?.(nextResult);
  }, [code, isStreaming, onParseComplete, parserConfig]);

  if (isStreaming) {
    return <EmptyForm className={className} message="Waiting for the generated form..." />;
  }

  if (!parseResult.success) {
    return <EmptyForm className={className} message={parseResult.error ?? 'Generated form could not be parsed.'} />;
  }

  const options: UseFormedibleOptions<FormedibleFormValues> = {
    ...parseResult.formOptions,
    formOptions: {
      ...parseResult.formOptions.formOptions,
      onSubmit: async ({ value }) => {
        await parseResult.formOptions.formOptions.onSubmit?.({ value });
        await onSubmit?.(value);
      },
    },
  };

  return <ParsedForm className={className} options={options} />;
}

export { parseAiToFormedible } from '@/lib/formedible/ai-parser';
export type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';

'use client';

import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import type { AIProvider, ProviderConfig } from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export const providerOptions = [
  { value: 'openai', label: 'OpenAI', defaultModel: 'gpt-4o-mini', requiresKey: true },
  { value: 'anthropic', label: 'Anthropic', defaultModel: 'claude-3-5-sonnet-latest', requiresKey: true },
  { value: 'google', label: 'Google Gemini', defaultModel: 'gemini-1.5-pro', requiresKey: true },
  { value: 'mistral', label: 'Mistral', defaultModel: 'mistral-large-latest', requiresKey: true },
  { value: 'openrouter', label: 'OpenRouter', defaultModel: 'openai/gpt-4o-mini', requiresKey: true },
  { value: 'openai-compatible', label: 'OpenAI Compatible', defaultModel: 'gpt-4o-mini', requiresKey: false },
] as const satisfies readonly { readonly value: AIProvider; readonly label: string; readonly defaultModel: string; readonly requiresKey: boolean }[];

export interface ProviderSelectionProps {
  readonly value: ProviderConfig;
  readonly onChange: (value: ProviderConfig) => void;
  readonly className?: string;
}

export function createDefaultProviderConfig(provider: AIProvider = 'openai'): ProviderConfig {
  const option = providerOptions.find((entry) => entry.value === provider) ?? providerOptions[0];

  return {
    provider: option.value,
    model: option.defaultModel,
    apiKey: '',
    temperature: 0.7,
    maxTokens: 4000,
  };
}

export function validateProviderConfig(config: ProviderConfig | null): string | undefined {
  if (!config) {
    return 'Provider configuration is required.';
  }

  const provider = providerOptions.find((entry) => entry.value === config.provider);

  if (!provider) {
    return 'Unsupported AI provider.';
  }

  if (provider.requiresKey && config.apiKey.trim().length === 0) {
    return `API key is required for ${provider.label}.`;
  }

  if (config.provider === 'openai-compatible' && (!config.endpoint || config.endpoint.trim().length === 0)) {
    return 'Endpoint is required for OpenAI-compatible provider.';
  }

  return undefined;
}

export function ProviderSelection({ value, onChange, className }: ProviderSelectionProps) {
  return (
    <div className={cn('grid gap-3 rounded-lg border p-3', className)}>
      <label className="grid gap-1 text-sm font-medium">
        Provider
        <Select
          value={value.provider}
          onValueChange={(providerValue) => {
            const provider = providerValue as AIProvider;
            onChange({ ...createDefaultProviderConfig(provider), apiKey: value.apiKey, endpoint: value.endpoint });
          }}
        >
          <SelectTrigger>
            <SelectValue placeholder="Select provider" />
          </SelectTrigger>
          <SelectContent>
            {providerOptions.map((provider) => (
              <SelectItem key={provider.value} value={provider.value}>
                {provider.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </label>
      <label className="grid gap-1 text-sm font-medium">
        Model
        <Input value={value.model} onChange={(event) => onChange({ ...value, model: event.target.value })} />
      </label>
      <label className="grid gap-1 text-sm font-medium">
        API key
        <Input value={value.apiKey} type="password" onChange={(event) => onChange({ ...value, apiKey: event.target.value })} />
      </label>
      {value.provider === 'openai-compatible' ? (
        <label className="grid gap-1 text-sm font-medium">
          API endpoint
          <Input value={value.endpoint ?? ''} placeholder="https://api.example.com/v1" onChange={(event) => onChange({ ...value, endpoint: event.target.value })} />
        </label>
      ) : null}
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="grid gap-1 text-sm font-medium">
          Temperature
          <Input value={value.temperature ?? ''} type="number" step="0.1" onChange={(event) => onChange({ ...value, temperature: Number(event.target.value) })} />
        </label>
        <label className="grid gap-1 text-sm font-medium">
          Max tokens
          <Input value={value.maxTokens ?? ''} type="number" step="1" onChange={(event) => onChange({ ...value, maxTokens: Number(event.target.value) })} />
        </label>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { validateProviderConfig } from '@/components/formedible/ai/provider-selection';
import { extractFormCode } from '@/lib/formedible/ai-parser';
import type {
  AiGenerationRequest,
  AiGenerationResult,
  AiMessage,
  AIBuilderMode,
  BackendConfig,
  ProviderConfig,
} from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface ChatInterfaceProps {
  readonly providerConfig: ProviderConfig | null;
  readonly mode: AIBuilderMode;
  readonly backendConfig?: BackendConfig;
  readonly messages: readonly AiMessage[];
  readonly onMessagesChange: (messages: readonly AiMessage[]) => void;
  readonly onFormGenerated?: (formCode: string) => void;
  readonly generateForm?: (request: AiGenerationRequest) => Promise<AiGenerationResult>;
  readonly conversationId?: string;
  readonly systemPrompt?: string;
  readonly className?: string;
}

export const DEFAULT_AI_SYSTEM_PROMPT = 'You are Formedible AI Builder. Return a valid Formedible form configuration in a fenced formedible code block when generating or changing a form.';

function createMessage(role: AiMessage['role'], content: string, formCode?: string): AiMessage {
  return {
    id: `${role}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    role,
    content,
    formCode,
    timestamp: Date.now(),
  };
}

function extractTextFromProviderPayload(payload: unknown): string {
  if (typeof payload === 'object' && payload !== null) {
    if ('content' in payload && typeof payload.content === 'string') {
      return payload.content;
    }

    if ('content' in payload && Array.isArray(payload.content)) {
      return payload.content
        .map((part: unknown) => (typeof part === 'object' && part !== null && 'text' in part && typeof part.text === 'string' ? part.text : ''))
        .join('');
    }

    if ('text' in payload && typeof payload.text === 'string') {
      return payload.text;
    }

    if ('choices' in payload && Array.isArray(payload.choices)) {
      const firstChoice: unknown = payload.choices[0];
      if (typeof firstChoice === 'object' && firstChoice !== null && 'message' in firstChoice) {
        const message: unknown = firstChoice.message;
        if (typeof message === 'object' && message !== null && 'content' in message && typeof message.content === 'string') {
          return message.content;
        }
      }

      if (typeof firstChoice === 'object' && firstChoice !== null && 'delta' in firstChoice) {
        const delta: unknown = firstChoice.delta;
        if (typeof delta === 'object' && delta !== null && 'content' in delta && typeof delta.content === 'string') {
          return delta.content;
        }
      }
    }

    if ('candidates' in payload && Array.isArray(payload.candidates)) {
      const firstCandidate: unknown = payload.candidates[0];
      if (typeof firstCandidate === 'object' && firstCandidate !== null && 'content' in firstCandidate) {
        const content: unknown = firstCandidate.content;
        if (typeof content === 'object' && content !== null && 'parts' in content && Array.isArray(content.parts)) {
          return content.parts
            .map((part: unknown) => (typeof part === 'object' && part !== null && 'text' in part && typeof part.text === 'string' ? part.text : ''))
            .join('');
        }
      }
    }
  }

  throw new Error('AI response must include string content.');
}

function parseSseText(text: string): string {
  return text
    .split('\n')
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim())
    .filter((line) => line.length > 0 && line !== '[DONE]')
    .map((line) => {
      try {
        return extractTextFromProviderPayload(JSON.parse(line));
      } catch {
        return line;
      }
    })
    .join('');
}

function getDirectEndpoint(config: ProviderConfig): string {
  if (config.provider === 'openai-compatible') {
    return `${config.endpoint?.replace(/\/$/, '')}/chat/completions`;
  }

  if (config.provider === 'openrouter') {
    return 'https://openrouter.ai/api/v1/chat/completions';
  }

  if (config.provider === 'openai') {
    return 'https://api.openai.com/v1/chat/completions';
  }

  if (config.provider === 'anthropic') {
    return 'https://api.anthropic.com/v1/messages';
  }

  if (config.provider === 'google') {
    return `https://generativelanguage.googleapis.com/v1beta/models/${config.model}:generateContent?key=${encodeURIComponent(config.apiKey)}`;
  }

  return 'https://api.mistral.ai/v1/chat/completions';
}

function createDirectHeaders(config: ProviderConfig): Readonly<Record<string, string>> {
  if (config.provider === 'anthropic') {
    return {
      'Content-Type': 'application/json',
      'x-api-key': config.apiKey,
      'anthropic-version': '2023-06-01',
    };
  }

  if (config.provider === 'google') {
    return { 'Content-Type': 'application/json' };
  }

  return {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${config.apiKey}`,
  };
}

function createDirectBody(config: ProviderConfig, request: AiGenerationRequest): unknown {
  const messages = request.messages.map((message) => ({ role: message.role === 'assistant' ? 'assistant' : 'user', content: message.content }));

  if (config.provider === 'anthropic') {
    return {
      model: config.model,
      system: request.systemPrompt,
      max_tokens: config.maxTokens,
      temperature: config.temperature,
      messages,
    };
  }

  if (config.provider === 'google') {
    return {
      systemInstruction: { parts: [{ text: request.systemPrompt }] },
      generationConfig: { temperature: config.temperature, maxOutputTokens: config.maxTokens },
      contents: request.messages.map((message) => ({ role: message.role === 'assistant' ? 'model' : 'user', parts: [{ text: message.content }] })),
    };
  }

  return {
    model: config.model,
    temperature: config.temperature,
    max_tokens: config.maxTokens,
    stream: false,
    messages: [{ role: 'system', content: request.systemPrompt }, ...request.messages.map((message) => ({ role: message.role, content: message.content }))],
  };
}

async function readAiResponse(response: Response): Promise<AiGenerationResult> {
  const contentType = response.headers.get('Content-Type') ?? '';
  let content: string;

  if (contentType.includes('application/json')) {
    content = extractTextFromProviderPayload(await response.json());
  } else {
    const text = await response.text();
    content = contentType.includes('text/event-stream') ? parseSseText(text) : text;
  }

  return { content, formCode: extractFormCode(content) };
}

async function requestBackend(config: BackendConfig, request: AiGenerationRequest): Promise<AiGenerationResult> {
  const response = await fetch(config.endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...config.headers,
    },
    body: JSON.stringify({
      messages: request.messages,
      systemPrompt: request.systemPrompt,
      userMessage: request.userMessage,
      providerConfig: request.providerConfig,
      conversationId: request.conversationId,
    }),
  });

  if (!response.ok) {
    throw new Error(`AI backend responded with ${response.status}`);
  }

  return readAiResponse(response);
}

async function requestDirectProvider(request: AiGenerationRequest): Promise<AiGenerationResult> {
  const validationError = validateProviderConfig(request.providerConfig);

  if (validationError) {
    throw new Error(validationError);
  }

  const providerConfig = request.providerConfig;

  if (!providerConfig) {
    throw new Error('Provider configuration is required.');
  }

  const response = await fetch(getDirectEndpoint(providerConfig), {
    method: 'POST',
    headers: createDirectHeaders(providerConfig),
    body: JSON.stringify(createDirectBody(providerConfig, request)),
  });

  if (!response.ok) {
    throw new Error(`AI provider responded with ${response.status}`);
  }

  return readAiResponse(response);
}

export async function generateAiFormCode(
  request: AiGenerationRequest,
  mode: AIBuilderMode,
  backendConfig?: BackendConfig,
  generateForm?: (request: AiGenerationRequest) => Promise<AiGenerationResult>,
): Promise<AiGenerationResult> {
  if (generateForm) {
    const result = await generateForm(request);
    return { ...result, formCode: result.formCode ?? extractFormCode(result.content) };
  }

  if (mode === 'backend' && backendConfig) {
    return requestBackend(backendConfig, request);
  }

  if (mode === 'direct') {
    return requestDirectProvider(request);
  }

  throw new Error('AI Builder requires backendConfig to generate a form in backend mode.');
}

export function ChatInterface({
  providerConfig,
  mode,
  backendConfig,
  messages,
  onMessagesChange,
  onFormGenerated,
  generateForm,
  conversationId,
  systemPrompt = DEFAULT_AI_SYSTEM_PROMPT,
  className,
}: ChatInterfaceProps) {
  const [prompt, setPrompt] = useState('');
  const [error, setError] = useState<string>();
  const [isGenerating, setIsGenerating] = useState(false);

  async function submitPrompt() {
    const trimmedPrompt = prompt.trim();

    if (!trimmedPrompt || isGenerating) {
      return;
    }

    const userMessage = createMessage('user', trimmedPrompt);
    const nextMessages = [...messages, userMessage];
    onMessagesChange(nextMessages);
    setPrompt('');
    setError(undefined);
    setIsGenerating(true);

    try {
      const result = await generateAiFormCode(
        { prompt: trimmedPrompt, providerConfig, messages: nextMessages, systemPrompt, userMessage, conversationId },
        mode,
        backendConfig,
        generateForm,
      );
      const assistantMessage = createMessage('assistant', result.content, result.formCode);
      onMessagesChange([...nextMessages, assistantMessage]);

      if (result.formCode) {
        onFormGenerated?.(result.formCode);
      }
    } catch (generationError) {
      setError(generationError instanceof Error ? generationError.message : String(generationError));
      onMessagesChange(nextMessages);
    } finally {
      setIsGenerating(false);
    }
  }

  return (
    <div className={cn('flex h-full flex-col gap-3', className)}>
      <div className="min-h-0 flex-1 space-y-3 overflow-auto rounded-lg border p-3">
        {messages.length === 0 ? <p className="text-sm text-muted-foreground">Describe the form you want to build.</p> : null}
        {messages.map((message) => (
          <article key={message.id} className={cn('rounded-md p-3 text-sm', message.role === 'user' ? 'bg-muted' : 'border')}>
            <p className="mb-1 font-medium capitalize">{message.role}</p>
            <p className="whitespace-pre-wrap">{message.content}</p>
          </article>
        ))}
      </div>
      {error ? <p className="rounded-md border border-destructive/40 p-2 text-sm text-destructive">{error}</p> : null}
      <div className="grid gap-2">
        <Textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder="Create a multi-step onboarding form..." />
        <Button type="button" disabled={isGenerating || prompt.trim().length === 0} onClick={submitPrompt}>
          {isGenerating ? 'Generating...' : 'Generate form'}
        </Button>
      </div>
    </div>
  );
}

export type { AiGenerationRequest, AiGenerationResult, AiMessage } from '@/lib/formedible/ai-types';

import { FormedibleParser } from '@/lib/formedible/formedible-parser';
import type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFieldConfig, FormedibleFormValues, FormediblePageConfig, FormedibleProgressConfig, UseFormedibleOptions } from '@/lib/formedible/types';

const requiredFieldKeys = new Set(['name', 'type']);

function filterRecordKeys<TRecord extends Readonly<Record<string, unknown>>>(value: TRecord, allowedKeys: readonly string[] | undefined): Record<string, unknown> {
  if (!allowedKeys) {
    return { ...value };
  }

  const allowedKeySet = new Set(allowedKeys);
  return Object.fromEntries(Object.entries(value).filter(([key]) => allowedKeySet.has(key)));
}

function filterField(field: FormedibleFieldConfig<FormedibleFormValues>, parserConfig?: AiParserConfig): FormedibleFieldConfig<FormedibleFormValues> {
  if (parserConfig?.allowedFieldTypes && (field.type === undefined || !parserConfig.allowedFieldTypes.includes(field.type))) {
    throw new Error(`Field type '${field.type}' is not allowed.`);
  }

  if (!parserConfig?.allowedFieldKeys) {
    return field;
  }

  const allowedFieldKeys = new Set(parserConfig.allowedFieldKeys);
  return Object.fromEntries(Object.entries(field).filter(([key]) => requiredFieldKeys.has(key) || allowedFieldKeys.has(key))) as FormedibleFieldConfig<FormedibleFormValues>;
}

function filterPages(pages: readonly FormediblePageConfig<FormedibleFormValues>[] | undefined, parserConfig?: AiParserConfig): readonly FormediblePageConfig<FormedibleFormValues>[] | undefined {
  if (!pages || !parserConfig?.allowedPageKeys) {
    return pages;
  }

  return pages.map((page) => filterRecordKeys(page, parserConfig.allowedPageKeys) as FormediblePageConfig<FormedibleFormValues>);
}

function filterProgress(progress: FormedibleProgressConfig | undefined, parserConfig?: AiParserConfig): FormedibleProgressConfig | undefined {
  if (!progress || !parserConfig?.allowedProgressKeys) {
    return progress;
  }

  return filterRecordKeys(progress, parserConfig.allowedProgressKeys) as FormedibleProgressConfig;
}

function applyParserAllowlists(options: UseFormedibleOptions<FormedibleFormValues>, parserConfig?: AiParserConfig): UseFormedibleOptions<FormedibleFormValues> {
  const formOptions = filterRecordKeys(options.formOptions, parserConfig?.allowedFormOptionsKeys) as UseFormedibleOptions<FormedibleFormValues>['formOptions'];
  const output: Record<string, unknown> = {
    ...options,
    fields: options.fields.map((field) => filterField(field, parserConfig)),
    formOptions,
  };

  if (options.pages !== undefined) {
    output.pages = filterPages(options.pages, parserConfig);
  }

  if (options.progress !== undefined) {
    output.progress = filterProgress(options.progress, parserConfig);
  }

  if (parserConfig?.allowedKeys) {
    const allowedTopLevelKeys = new Set(parserConfig.allowedKeys);
    for (const key of Object.keys(output)) {
      if (key !== 'fields' && key !== 'formOptions' && !allowedTopLevelKeys.has(key)) {
        delete output[key];
      }
    }
  }

  return output as UseFormedibleOptions<FormedibleFormValues>;
}

function defaultValueForField(field: FormedibleFieldConfig<FormedibleFormValues>): unknown {
  if (field.type === 'checkbox' || field.type === 'switch') {
    return false;
  }

  if (field.type === 'number' || field.type === 'slider' || field.type === 'rating' || field.type === 'duration') {
    return 0;
  }

  if (field.type === 'multiSelect' || field.type === 'array') {
    return [];
  }

  if (field.type === 'object' || field.type === 'location') {
    return {};
  }

  return '';
}

function inferDefaultValues(options: UseFormedibleOptions<FormedibleFormValues>): UseFormedibleOptions<FormedibleFormValues> {
  const existingDefaults = options.formOptions.defaultValues;
  const defaultValues: FormedibleFormValues = { ...existingDefaults };

  for (const field of options.fields) {
    if (!Object.prototype.hasOwnProperty.call(defaultValues, field.name)) {
      defaultValues[field.name] = defaultValueForField(field);
    }
  }

  return {
    ...options,
    formOptions: {
      ...options.formOptions,
      defaultValues,
    },
  };
}

export function parseAiToFormedible(code: string, parserConfig?: AiParserConfig): AiFormParseResult {
  try {
    const parsed = FormedibleParser.parse(code, { strictValidation: parserConfig?.strictValidation ?? true });
    const allowedFormOptions = applyParserAllowlists(parsed, parserConfig);
    const formOptions = parserConfig?.inferDefaultValues === false ? allowedFormOptions : inferDefaultValues(allowedFormOptions);

    return {
      schema: formOptions.schema,
      formOptions,
      success: true,
    };
  } catch (error) {
    return {
      schema: undefined,
      formOptions: { fields: [], formOptions: { defaultValues: {} } },
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

export function extractFormCode(content: string): string | undefined {
  const formedibleBlock = content.match(/```(?:formedible|json|ts|tsx|typescript)?\s*([\s\S]*?fields\s*:[\s\S]*?)```/i);

  if (formedibleBlock?.[1]) {
    return formedibleBlock[1].trim();
  }

  const objectStart = content.indexOf('{');
  const fieldsIndex = content.indexOf('fields');
  const objectEnd = content.lastIndexOf('}');

  if (objectStart !== -1 && fieldsIndex > objectStart && objectEnd > fieldsIndex) {
    return content.slice(objectStart, objectEnd + 1).trim();
  }

  return undefined;
}

